SELECT (DATE_TRUNC('DAY', "RATE_DAY")) AS "TIME_BUCKET", (CAST(CASE WHEN ((CAST(CASE WHEN (SUM(SUM(COMPUTE_RATE_ROWS)) OVER ()) = 0 OR (SUM(SUM(COMPUTE_RATE_ROWS)) OVER ()) IS NULL THEN NULL ELSE CAST((SUM(SUM(COMPUTE_RATE)) OVER ()) AS DECIMAL(38, 15)) / CAST((SUM(SUM(COMPUTE_RATE_ROWS)) OVER ()) AS DECIMAL(38, 15)) END AS DECIMAL(38, 15)))) = 0 OR ((CAST(CASE WHEN (SUM(SUM(COMPUTE_RATE_ROWS)) OVER ()) = 0 OR (SUM(SUM(COMPUTE_RATE_ROWS)) OVER ()) IS NULL THEN NULL ELSE CAST((SUM(SUM(COMPUTE_RATE)) OVER ()) AS DECIMAL(38, 15)) / CAST((SUM(SUM(COMPUTE_RATE_ROWS)) OVER ()) AS DECIMAL(38, 15)) END AS DECIMAL(38, 15)))) IS NULL THEN NULL ELSE CAST(((CAST(CASE WHEN (SUM(COMPUTE_RATE_ROWS)) = 0 OR (SUM(COMPUTE_RATE_ROWS)) IS NULL THEN NULL ELSE CAST((SUM(COMPUTE_RATE)) AS DECIMAL(38, 15)) / CAST((SUM(COMPUTE_RATE_ROWS)) AS DECIMAL(38, 15)) END AS DECIMAL(38, 15)))) AS DECIMAL(38, 15)) / CAST(((CAST(CASE WHEN (SUM(SUM(COMPUTE_RATE_ROWS)) OVER ()) = 0 OR (SUM(SUM(COMPUTE_RATE_ROWS)) OVER ()) IS NULL THEN NULL ELSE CAST((SUM(SUM(COMPUTE_RATE)) OVER ()) AS DECIMAL(38, 15)) / CAST((SUM(SUM(COMPUTE_RATE_ROWS)) OVER ()) AS DECIMAL(38, 15)) END AS DECIMAL(38, 15)))) AS DECIMAL(38, 15)) END AS DECIMAL(38, 15))) AS "ORG_RATE_PREMIUM" FROM (SELECT "ACCOUNT_NAME" AS ACCOUNT_NAME, "ACCOUNT_LOCATOR" AS ACCOUNT_LOCATOR, "ORGANIZATION_NAME" AS ORGANIZATION_NAME, "CONTRACT_NUMBER" AS CONTRACT_NUMBER, "REGION" AS REGION, "SERVICE_LEVEL" AS SERVICE_LEVEL, "SERVICE_TYPE" AS SERVICE_TYPE, "USAGE_TYPE" AS USAGE_TYPE, "CURRENCY" AS CURRENCY, CAST("RATE_SHEET_DATE" AS DATE) AS RATE_DAY, (CAST("EFFECTIVE_RATE" AS DECIMAL(38, 9))) AS EFFECTIVE_RATE, (CAST(CASE WHEN "USAGE_TYPE" = 'compute' THEN "EFFECTIVE_RATE" END AS DECIMAL(38, 9))) AS COMPUTE_RATE, CASE WHEN "USAGE_TYPE" = 'compute' THEN 1 ELSE 0 END AS COMPUTE_RATE_ROWS FROM rate_sheet_daily) AS base GROUP BY (DATE_TRUNC('DAY', "RATE_DAY")) ORDER BY "ORG_RATE_PREMIUM" DESC, "TIME_BUCKET" LIMIT 100
